package com.bautruc.ecommerce.commerce.application;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;class CheckoutRequestHasherTest{@Test void isDeterministicAndSensitiveToLogicalFields(){CheckoutRequestHasher h=new CheckoutRequestHasher();var a=new NormalizedCheckoutRequest("A","09000000","a@example.com","X",null);assertThat(h.hash(a)).hasSize(64).isEqualTo(h.hash(a));assertThat(h.hash(a)).isNotEqualTo(h.hash(new NormalizedCheckoutRequest("A","09000000","a@example.com","Y",null)));}}
